package com.hmdp.ai.runtime.knowledge.chunking;
import com.hmdp.ai.domain.knowledge.ChunkFragment;import com.hmdp.ai.domain.knowledge.ChunkingPolicy;import com.hmdp.ai.domain.knowledge.parsing.ParsedDocument;import org.springframework.stereotype.Component;import java.util.*;
@Component public class SemanticBoundaryChunkingStrategy implements ChunkingStrategy {public String code(){return "SEMANTIC_BOUNDARY";}public List<ChunkFragment> chunk(ParsedDocument d,ChunkingPolicy p){List<ChunkFragment>out=new ArrayList<>();StringBuilder group=new StringBuilder();for(String sentence:d.getPlainText().split("(?<=[。！？.!?])")){if(group.length()>0&&group.length()+sentence.length()>p.getMaxChars()){out.add(new ChunkFragment(group.toString().trim(),null,d.getTitle(),null,null,null,null,null,null,null,null));group.setLength(0);}group.append(sentence);}if(group.length()>0)out.add(new ChunkFragment(group.toString().trim(),null,d.getTitle(),null,null,null,null,null,null,null,null));return out;}}
